-- Paper: Hyprland visual layer. Generated by rice-render from palette.toml.
-- Loaded from hyprland.lua via ~/.local/share/rice/active/hypr.lua.
--
-- Sheets on a desk: no borders, no blur, no transparency. Shadows do the
-- separating: the focused window casts a darker one, as if lifted off the
-- desk. (Hyprland has one shadow range for every window, and no window rule
-- for it, so only the colour differs between active and inactive.)

-- Everything that changes with light and dark (colours, shadows, the grain)
-- is in hypr-mode.lua beside this file, loaded at the end, so this file is
-- the same in both modes.

hl.config({
    general = {
        gaps_in     = {{ shape.gaps_in }},
        gaps_out    = {{ shape.gaps_out }},
        border_size = {{ shape.border }},
    },

    decoration = {
        rounding         = {{ shape.window }},
        rounding_power   = {{ shape.rounding_power }},
        active_opacity   = 1.0,
        inactive_opacity = 1.0,
        dim_inactive     = false,

        -- paper isn't glass
        blur = { enabled = false },

        shadow = {
            enabled      = true,
            render_power = 3,
        },
    },

    group = {
        groupbar = {
            enabled              = true,
            height               = 18,
            indicator_height     = 0,
            gradients            = true,
            rounding             = {{ shape.chip }},
            gradient_rounding    = {{ shape.chip }},
            font_family          = "{{ fonts.hand }}",
            font_size            = 13,
            font_weight_active   = {{ fonts.weight_strong }},
            font_weight_inactive = {{ fonts.weight }},
        },
    },

    animations = { enabled = true },
})

---------------------------------------------------------------------------
-- Motion: a sheet dropped onto the desk, tossed away, pages turned
---------------------------------------------------------------------------
hl.curve("drop", { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} }, { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.curve("toss", { type = "bezier", points = { { {{ motion.sink.0 }}, {{ motion.sink.1 }} }, { {{ motion.sink.2 }}, {{ motion.sink.3 }} } } })
hl.curve("turn", { type = "bezier", points = { { {{ motion.turn.0 }}, {{ motion.turn.1 }} }, { {{ motion.turn.2 }}, {{ motion.turn.3 }} } } })

-- speed is in deciseconds
hl.animation({ leaf = "windowsIn",   enabled = true, speed = {{ motion.open | div(100) }},      bezier = "drop", style = "slide top" })
-- the closest Hyprland gets to crumpling: shrink away fast
hl.animation({ leaf = "windowsOut",  enabled = true, speed = {{ motion.close | div(100) }},     bezier = "toss", style = "popin 60%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = {{ motion.move | div(100) }},      bezier = "drop" })
-- page turns: workspaces slide sideways and the shell's page-turn layer
-- (paper/turn/PageTurn.qml) draws the turning page's back along the seam,
-- on the same curve and duration
hl.animation({ leaf = "workspaces",  enabled = true, speed = {{ motion.workspace | div(100) }}, bezier = "turn", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = {{ motion.scratchpad | div(100) }}, bezier = "drop", style = "slidevert" })
hl.animation({ leaf = "layersIn",    enabled = true, speed = {{ motion.panel_in | div(100) }},  bezier = "drop", style = "slide top" })
hl.animation({ leaf = "layersOut",   enabled = true, speed = {{ motion.panel_out | div(100) }}, bezier = "toss", style = "fade" })
hl.animation({ leaf = "fade",        enabled = true, speed = {{ motion.focus | div(100) }},     bezier = "default" })
hl.animation({ leaf = "border",      enabled = false })
hl.animation({ leaf = "borderangle", enabled = false })

---------------------------------------------------------------------------
-- Styling the base layer's window tags. Paper has no transparency: every
-- tag is opaque, and nothing is blurred.
---------------------------------------------------------------------------
hl.window_rule({ name = "paper-opaque", match = { tag = "opaque" }, opacity = "1.0 override 1.0 override" })
hl.window_rule({ name = "paper-glassy", match = { tag = "glassy" }, opacity = "1.0 override 1.0 override" })
-- small tools (pavucontrol, nm-connection-editor, file pickers): an index
-- card's worth of window, centred
hl.window_rule({ name = "paper-dialog", match = { tag = "dialog" }, size = { "640", "460" }, center = true })
hl.window_rule({ name = "paper-pip", match = { tag = "pip" }, rounding = {{ shape.chip }} })
hl.window_rule({ name = "paper-fullscreen", match = { fullscreen = true }, rounding = 0, no_shadow = true })
hl.window_rule({
    name = "paper-game", match = { tag = "game" },
    no_anim = true, no_shadow = true, opacity = "1.0 override 1.0 override",
})

---------------------------------------------------------------------------
-- Quickshell surfaces. The shell animates the bar, the desk widgets, the
-- notes and the OSD itself; Hyprland drops the launcher, the control
-- centre, the power card and the key sheet in from the top. No blur.
---------------------------------------------------------------------------
hl.layer_rule({ name = "paper-wallpaper", match = { namespace = "^paper-wallpaper$" }, no_anim = true })
hl.layer_rule({ name = "paper-still", match = { namespace = "^paper-(bar|desk|island|osd|turn)$" }, no_anim = true })

---------------------------------------------------------------------------
-- The mode's colours, shadows and grain (beside this file in build/<mode>/)
---------------------------------------------------------------------------
local here = debug.getinfo(1, "S").source:match("^@(.*/)") or
    ((os.getenv("XDG_DATA_HOME") or (os.getenv("HOME") .. "/.local/share")) .. "/rice/active/")
dofile(here .. "hypr-mode.lua")
